<script setup>
import {ref,reactive,computed,provide,toRef,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import WizardStepper from './WizardStepper.vue';
import StepFiles from './steps/StepFiles.vue';
import StepDetails from './steps/StepDetails.vue';
import StepCompat from './steps/StepCompat.vue';
import StepSummary from './steps/StepSummary.vue';
import SettingsIcon from './SettingsIcon.vue';
import {productNameError,reservedUploadName,uploadValidation} from '../lib/productValidation';
import {closeModalSurface} from '../lib/modalMotion';
import {size,categories} from '../lib/catalog';
import SwitchCard from './SwitchCard.vue';
import FileList from './FileList.vue';
import ChipInput from './ChipInput.vue';
import SearchDropdown from './SearchDropdown.vue';
import '../styles/product-wizard.css';
const props=defineProps({avatars:{type:Array,default:()=>[]},tagOptions:{type:Array,default:()=>[]},categoryUsage:{type:Object,default:()=>({})}});const emit=defineEmits(['close','added']);
const form=reactive({name:'',category:'',avatars:[],tags:[],adult:false,generic:false,files:[],previewFile:null,previewUrl:'',autoName:false});
const step=ref(1),furthest=ref(1),editing=ref(false),direction=ref('forward'),dialog=ref(),discardDialog=ref(),body=ref(),busy=ref(false),error=ref(''),progress=ref(''),fileNotice=ref(''),token=ref(''),announcement=ref('');
const selectedCategories=ref([]);
watch(selectedCategories,values=>{form.category=values[0]||'';});
const coverPicker=ref(),filePicker=ref(),moreOpen=ref(false);let manualCover=false;
const popularCategories=computed(()=>Object.keys(categories).sort((a,b)=>(props.categoryUsage[b]||0)-(props.categoryUsage[a]||0)).slice(0,4));
const otherCategories=computed(()=>Object.keys(categories).filter(c=>!popularCategories.value.includes(c)));
const previewDetail=computed(()=>[selectedCategories.value.map(c=>categories[c]).join(', ')||'Sin categoría',form.generic?'Genérico':form.avatars.join(', ')].filter(Boolean).join(' · '));
function pickCover(e){const file=e.target.files[0];if(file){manualCover=true;setPreview(file);}e.target.value='';}
function dropCover(e){if(frozen.value)return;const file=[...e.dataTransfer.files].find(f=>/\.(png|jpe?g|webp)$/i.test(f.name));if(file){manualCover=true;setPreview(file);}}
function removeFile(file){if(!frozen.value)form.files.splice(form.files.indexOf(file),1);}
watch(()=>form.files.slice(),files=>{if(manualCover)return;const image=files.find(f=>/\.(png|jpe?g|webp)$/i.test(f.name));if(image!==form.previewFile){if(image)setPreview(image);else clearPreview();}});
let done=new Set(),previousFocus,discardFocus;
const stepNames=['Archivos','Detalles','Compatibilidad','Resumen'];const components=[StepFiles,StepDetails,StepCompat,StepSummary];
const frozen=computed(()=>busy.value||!!token.value);const totalSize=computed(()=>form.files.reduce((sum,f)=>sum+f.size,0));
const uploadFiles=computed(()=>form.previewFile?[new File([form.previewFile],'__preview.'+form.previewFile.name.split('.').pop().toLowerCase(),{type:form.previewFile.type}),...form.files]:form.files);
const validationErrors=computed(()=>uploadValidation(form.name,form.files,form.previewFile));
const detailsValid=computed(()=>!productNameError(form.name)&&!!form.category);const valid=computed(()=>form.files.length>0&&detailsValid.value&&!validationErrors.value.length);
const stepValid=computed(()=>step.value===1?form.files.length>0:step.value===2?detailsValid.value:step.value===3?true:valid.value);
const dirty=computed(()=>!!(form.name||form.category||form.files.length||form.previewFile||form.avatars.length||form.tags.length||form.generic||form.adult));
const status=computed(()=>{if(busy.value)return progress.value||'Agregando…';if(step.value===1)return form.files.length?form.files.length+' archivos · '+size(totalSize.value):'Agregá al menos un archivo';if(step.value===2&&!detailsValid.value){const missing=[];if(!form.name.trim())missing.push('nombre');if(!form.category)missing.push('categoría');return 'Falta: '+missing.join(' y ');}if(step.value===4)return 'Revisá y confirmá. Podés editar cualquier sección.';return form.files.length+' archivos listos · '+size(totalSize.value);});
function clearPreview(){if(frozen.value)return;if(form.previewUrl)URL.revokeObjectURL(form.previewUrl);form.previewUrl='';form.previewFile=null;}
function setPreview(file){if(frozen.value||!file)return;if(!/\.(png|jpe?g|webp)$/i.test(file.name)){fileNotice.value='La portada debe ser JPG, PNG o WebP.';return;}clearPreview();form.previewFile=file;form.previewUrl=URL.createObjectURL(file);fileNotice.value='';error.value='';}
function autoComplete(){if(!form.name){const main=form.files.find(f=>/\.unitypackage$/i.test(f.name))||form.files.find(f=>/\.(zip|rar)$/i.test(f.name));if(main){form.name=main.name.replace(/\.[^.]+$/,'').replace(/_/g,' ');form.autoName=true;}}}
function addFiles(incoming){if(frozen.value)return;const notices=[];for(const file of incoming){if(form.files.some(f=>f.name.toLocaleLowerCase()===file.name.toLocaleLowerCase())){notices.push('«'+file.name+'» ya está en la lista.');continue;}if(/\.(exe|msi|bat|cmd|ps1|com|scr|lnk)$/i.test(file.name)||!file.name.includes('.')){notices.push('«'+file.name+'» no es un formato de recurso compatible.');continue;}if(reservedUploadName(file.name)){notices.push('Ese nombre está reservado para la portada.');continue;}form.files.push(file);}fileNotice.value=notices.join(' ');autoComplete();}
function canGo(target){if(target>=2&&!form.files.length)return false;if(target>=3&&!detailsValid.value)return false;return true;}
async function go(target){if(busy.value||target<1||target>4||!canGo(target))return;if(step.value===1&&target>1)autoComplete();direction.value=target<step.value?'backward':'forward';furthest.value=Math.max(furthest.value,target);step.value=target;announcement.value='Paso '+target+' de 4: '+stepNames[target-1];await nextTick();if(body.value)body.value.scrollTop=0;}
function editStep(target){if(frozen.value)return;editing.value=true;go(target);}
function stepperNavigate(target){if(target<=furthest.value&&!busy.value)go(target);}
function next(){if(busy.value||!stepValid.value)return;if(step.value===4){submit();return;}if(step.value===1)autoComplete();if(editing.value){if(valid.value){editing.value=false;go(4);}return;}go(step.value+1);}
function back(){if(busy.value)return;if(step.value===1)requestClose();else go(step.value-1);}
function closeForm(){return closeModalSurface(dialog.value,()=>emit('close'));}
async function discardForm(){if(busy.value)return;busy.value=true;try{if(token.value)await request('/api/upload/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token.value})});token.value='';await closeModalSurface(discardDialog.value,()=>{discardDialog.value.close();closeForm();});}catch(e){error.value='No se pudo cancelar la carga: '+e.message;}finally{busy.value=false;}}
function requestClose(){if(busy.value)return;if(!dirty.value){closeForm();return;}discardFocus=document.activeElement;discardDialog.value.showModal();}
function keepEditing(){closeModalSurface(discardDialog.value,()=>{discardDialog.value.close();discardFocus?.focus();});}
function backdrop(e){if(e.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)requestClose();}
function paste(e){if(frozen.value||discardDialog.value?.open||e.target.closest('input,textarea,[contenteditable="true"]'))return;const image=[...e.clipboardData.items].find(item=>item.type.startsWith('image/'));if(image){e.preventDefault();manualCover=true;setPreview(image.getAsFile());}}
function keys(e){if(discardDialog.value?.open||!dialog.value?.open)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();submit();return;}if(e.key==='Enter'&&!e.target.closest('button,[role="combobox"],[role="listbox"]'))e.preventDefault();if(e.key==='Tab'){const controls=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(el=>el.getClientRects().length&&!el.hidden);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
async function request(url,options){const r=await fetch(url,options),data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo guardar');return data;}
async function submit(){if(busy.value||!valid.value)return;busy.value=true;error.value='';try{
if(!token.value){const data=await request('/api/upload/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.name.trim(),category:form.category,avatars:form.avatars,tags:[...new Set([...form.tags,...selectedCategories.value.slice(1).map(c=>categories[c])])].join(', '),adult:form.adult,generic:form.generic,files:uploadFiles.value.map(f=>({name:f.name,size:f.size}))})});token.value=data.token;}
for(let i=0;i<uploadFiles.value.length;i++){const f=uploadFiles.value[i];if(done.has(f.name))continue;progress.value='Subiendo '+(i+1)+' de '+uploadFiles.value.length+': '+f.name;await request('/api/upload/file?token='+encodeURIComponent(token.value)+'&name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f});done.add(f.name);}
progress.value=window.__VRC_DESKTOP__?'Comprimiendo y verificando ZIP…':'Guardando producto…';const result=await request('/api/upload/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token.value})});await closeModalSurface(dialog.value,()=>emit('added',result.path));
}catch(e){error.value=e.message;}finally{busy.value=false;}}
provide('productWizard',{form,frozen,addFiles,fileNotice,totalSize,setPreview,clearPreview,uploadFiles,editStep,avatarOptions:toRef(props,'avatars'),tagOptions:toRef(props,'tagOptions'),zipEnabled:Boolean(window.__VRC_DESKTOP__)});
async function focusStep(){await nextTick();const selector='#compact-name';body.value?.querySelector(selector)?.focus();}
onMounted(async()=>{previousFocus=document.activeElement;dialog.value.showModal();document.addEventListener('paste',paste);document.addEventListener('keydown',keys);announcement.value='Paso 1 de 4: Archivos';await focusStep();});
onBeforeUnmount(()=>{document.removeEventListener('paste',paste);document.removeEventListener('keydown',keys);if(form.previewUrl)URL.revokeObjectURL(form.previewUrl);if(discardDialog.value?.open)discardDialog.value.close();if(dialog.value?.open)dialog.value.close();previousFocus?.focus();});
</script>
<template><dialog ref="dialog" class="product-wizard-dialog add-product-dialog mochi-night all-product-dialog compact-a5" aria-labelledby="all-product-title" @cancel.prevent="requestClose" @click="backdrop"><form class="product-form" :aria-busy="busy" @submit.prevent="submit" @click="!$event.target.closest('.compact-category-more') && (moreOpen=false)"><header class="product-modal-header"><h2 id="all-product-title">Agregar producto</h2><button class="product-icon-button" type="button" :disabled="busy" aria-label="Cerrar" @click="requestClose"><SettingsIcon name="x"/></button></header><div ref="body" class="product-modal-body compact-a5-body"><aside class="compact-a5-left"><div class="compact-live-card"><div class="compact-live-cover" @dragover.prevent @drop.prevent="dropCover"><button class="compact-cover-picker" type="button" :disabled="frozen" aria-label="Elegir portada" @click="coverPicker.click()"><img v-if="form.previewUrl" :class="{blurred:form.adult}" :src="form.previewUrl" alt="Portada del producto"/><span v-else><SettingsIcon name="image"/><small>Arrastrá una portada o hacé clic</small></span></button><span v-if="form.adult" class="compact-adult-mark">R18 · difuminado</span><button type="button" class="compact-cover-change" :disabled="frozen" @click="coverPicker.click()">Cambiar</button></div><div class="compact-live-copy"><strong>{{form.name||'Nombre del producto'}}</strong><p>{{previewDetail}}</p></div></div><input ref="coverPicker" type="file" hidden accept="image/png,image/jpeg,image/webp" :disabled="frozen" @change="pickCover"/><SwitchCard v-model="form.adult" title="Contenido R18" description="Difumina la portada en la grilla" :disabled="frozen"/><SwitchCard v-model="form.generic" title="Genérico" description="Sirve para cualquier avatar" :disabled="frozen"/></aside><div class="compact-a5-right"><div class="compact-fields-grid"><label for="compact-name">Nombre</label><input id="compact-name" v-model="form.name" :disabled="frozen" maxlength="180" placeholder="Nombre del producto" @input="form.autoName=false"/><label id="compact-category-label">Categoría</label><div class="compact-category-dropdown"><SearchDropdown v-model="selectedCategories" :options="Object.entries(categories).map(([value,label])=>({value,label}))" label="categorías" multiple night :disabled="frozen"/></div><label for="compact-avatars" :class="{'compact-disabled-label':form.generic}">Avatares</label><div class="compact-avatar-field" :class="{disabled:form.generic}"><SearchDropdown v-model="form.avatars" :options="avatars.map(value=>({value,label:value}))" label="avatares" multiple night :disabled="frozen||form.generic"/><p v-if="form.generic" class="compact-generic-hint">Marcado como genérico — sirve para cualquier avatar</p></div><label for="compact-tags">Tags</label><SearchDropdown v-model="form.tags" :options="tagOptions.map(value=>({value,label:value}))" label="tags" multiple night allow-create :disabled="frozen"/></div><section class="compact-files-section"><header><h3>Archivos <span>· {{size(totalSize)}}</span></h3><button type="button" :disabled="frozen" @click="filePicker.click()">+ Elegir</button></header><input ref="filePicker" type="file" hidden multiple :disabled="frozen" @change="addFiles([...$event.target.files]);$event.target.value=''"/><FileList :files="form.files" :preview-file="form.previewFile" :disabled="frozen" @add="addFiles" @remove="removeFile"/><p v-if="fileNotice" class="product-inline-notice" role="status">{{fileNotice}}</p></section></div></div><div v-if="validationErrors.length" class="product-error-strip" role="alert"><p v-for="message in validationErrors" :key="message">{{message}}</p></div><div v-if="error" class="product-error-strip" role="alert">{{error}}</div><p v-if="busy" class="all-product-progress" role="status">{{progress}}</p><footer class="product-modal-footer compact-a5-footer"><button type="button" class="compact-cancel" :disabled="busy" @click="requestClose">Cancelar</button><button class="product-submit" type="submit" :disabled="busy||!valid">{{busy?'Agregando…':token?'Reintentar':'Agregar producto'}}</button></footer></form></dialog><dialog ref="discardDialog" class="product-discard-dialog mochi-night" aria-labelledby="all-discard-title" @cancel.prevent="keepEditing"><h3 id="all-discard-title">¿Descartar este producto?</h3><p>Se perderán los datos que todavía no guardaste. Las cargas temporales de esta sesión se retirarán.</p><p v-if="error" role="alert">{{error}}</p><div><button type="button" class="product-cancel" @click="keepEditing">Seguir editando</button><button type="button" class="product-submit"  :disabled="busy" @click="discardForm">{{busy?'Cancelando…':'Descartar'}}</button></div></dialog></template>